"use client";
import {ArtemisScope} from "./artemis-scope";
import View0 from "./components/performance-report/variants/01-report";
import View1 from "./components/performance-report/variants/02-comparison";
import View2 from "./components/performance-report/variants/03-team";
const views={"report":View0,"comparison":View1,"team":View2};
export interface ArtemisPerformanceReportProps {className?:string;variant?:"report"|"comparison"|"team";}
export function ArtemisPerformanceReport({className,variant="report"}:ArtemisPerformanceReportProps){const View=views[variant];return <ArtemisScope className={className}><View/></ArtemisScope>;}

"use client";
// @zeus-internal
import { ArtemisSwitch } from "../../../lib/switch";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { artemisCreatePortal } from "../../../artemis-scope";
import { useEffect, useId, useMemo, useRef, useState, type KeyboardEvent as ReactKeyboardEvent } from "react";
import { ARTEMIS_SPRING_LAYOUT, ARTEMIS_SPRING_PRESS } from "../../../lib/ease";
import { ReportChart } from "./01-report/chart";
import { CalendarDaysIcon, ChartColumnIcon, ChartLineIcon, CheckCheckIcon, ChevronDownIcon, Clock3Icon, DownloadIcon, TimerIcon, UsersIcon, } from "./01-report/icons";
import { buildReport, formatPeriod, INITIAL_FILTERS, longDate, reportCsv, TEAMS, type MetricId, type ReportingFilters, type TeamId, } from "./01-report/model";
import { Calendar, type DayRange, SessionContext } from "./01-report/calendar";
import { Surface } from "./01-report/surface";
import { TeamMenu } from "./01-report/team-menu";
import { Roller } from "./01-report/roller";
const METRIC_ICON: Record<MetricId, typeof TimerIcon> = {
    completed: CheckCheckIcon,
    hours: TimerIcon,
    onTime: Clock3Icon,
    active: UsersIcon,
};
const TEAM_OPTIONS = TEAMS.map((t) => ({ value: t.id, label: t.label }));
const FOCUS = "art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background";
const PILL = `art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:border art:border-border art:bg-transparent art:text-foreground art:hover:bg-primary/5 art:gap-2 ${FOCUS} art:text-sm art:rounded-full`;
const TONE = {
    positive: "text-success-foreground",
    negative: "text-destructive",
    neutral: "text-muted-foreground",
} as const;
const PRESS = { whileHover: { scale: 1.01 }, whileTap: { scale: 0.99 }, transition: ARTEMIS_SPRING_PRESS } as const;
const INDICATOR_SPRING = { type: "spring", stiffness: 170, damping: 24, mass: 1.2 } as const;
function CompareSwitch(props: {
    checked: boolean;
    onCheckedChange: (value: boolean) => void;
}) { return <ArtemisSwitch {...props} label="Compare"/>; }
export default function PerformanceReportReport() {
    const [filters, setFilters] = useState<ReportingFilters>(INITIAL_FILTERS);
    const [metric, setMetric] = useState<MetricId>("completed");
    const [kind, setKind] = useState<"bar" | "line">("bar");
    const headingId = useId();
    const pillId = useId();
    const chartIds = useId();
    const onChartTabKey = (e: ReactKeyboardEvent<HTMLDivElement>) => {
        const kinds = ["bar", "line"] as const;
        const tabs = Array.from(e.currentTarget.querySelectorAll<HTMLButtonElement>("[role=\"tab\"]"));
        if (!tabs.some((t) => t === document.activeElement))
            return;
        const current = kinds.indexOf(kind);
        let next = current;
        if (e.key === "ArrowRight")
            next = (current + 1) % tabs.length;
        else if (e.key === "ArrowLeft")
            next = (current - 1 + tabs.length) % tabs.length;
        else if (e.key === "Home")
            next = 0;
        else if (e.key === "End")
            next = tabs.length - 1;
        else
            return;
        e.preventDefault();
        tabs[next]?.focus();
        const nextKind = kinds[next];
        if (nextKind)
            setKind(nextKind);
    };
    const reduce = useReducedMotion();
    const [previousOn, setPreviousOn] = useState(true);
    const [periodOpen, setPeriodOpen] = useState(false);
    const periodBase = useId();
    const periodTriggerId = `${periodBase}-trigger`;
    const periodContentId = `${periodBase}-content`;
    const periodRootRef = useRef<HTMLDivElement>(null);
    const [periodDraft, setPeriodDraft] = useState<DayRange | null>(null);
    const periodValue = useMemo(() => ({ from: filters.range.start, to: filters.range.end }), [filters.range]);
    const periodTriggerRef = useRef<HTMLButtonElement>(null);
    const closePeriod = () => {
        setPeriodOpen(false);
        setPeriodDraft(null);
        if (document.getElementById(periodContentId)?.contains(document.activeElement)) {
            periodTriggerRef.current?.focus({ preventScroll: true });
        }
    };
    useEffect(() => {
        if (!periodOpen)
            return;
        const onKey = (e: KeyboardEvent) => {
            if (e.key === "Escape")
                closePeriod();
        };
        const onDown = (e: PointerEvent) => {
            const t = e.target as Node;
            if (periodRootRef.current?.contains(t) || document.getElementById(periodContentId)?.contains(t))
                return;
            closePeriod();
        };
        window.addEventListener("keydown", onKey);
        window.addEventListener("pointerdown", onDown);
        return () => {
            window.removeEventListener("keydown", onKey);
            window.removeEventListener("pointerdown", onDown);
        };
    });
    const [mounted, setMounted] = useState(false);
    useEffect(() => setMounted(true), []);
    const view = useMemo(() => buildReport(filters), [filters]);
    const active = view.metrics.find((m) => m.spec.id === metric) ?? view.metrics[0];
    const triggerText = !periodDraft
        ? formatPeriod(filters.range)
        : periodDraft.to
            ? formatPeriod({ start: periodDraft.from, end: periodDraft.to })
            : periodDraft.from
                ? `${longDate(periodDraft.from)} \u2013 Select end`
                : "Select dates";
    const periodLabel = `${longDate(filters.range.start)} to ${longDate(filters.range.end)}`;
    const [exported, setExported] = useState(false);
    const exportCsv = () => {
        setExported(true);
        const { filename, body } = reportCsv(filters);
        const url = URL.createObjectURL(new Blob([body], { type: "text/csv;charset=utf-8" }));
        const a = document.createElement("a");
        a.href = url;
        a.download = filename;
        a.click();
        URL.revokeObjectURL(url);
    };
    return (<div className="art:w-full art:max-w-7xl">
      <section aria-labelledby={headingId} aria-busy="false" className="art:@container art:w-full art:min-w-0 art:space-y-4">
        <header className="art:flex art:flex-wrap art:items-end art:justify-between art:gap-5">
          <div>
            <h2 id={headingId} className="art:text-2xl art:font-normal art:tracking-tight art:text-muted-foreground">Overview</h2>
            <p className="art:mt-2 art:text-sm art:text-muted-foreground">A closer look at your team&apos;s daily activity.</p>
          </div>
          <fieldset aria-label="Reporting controls" className="art:flex art:min-w-0 art:flex-wrap art:items-center art:gap-2">
            <div ref={periodRootRef} className="art:relative art:inline-flex art:max-w-full">
              <motion.button ref={periodTriggerRef} layout={!reduce} transition={{ layout: ARTEMIS_SPRING_LAYOUT }} id={periodTriggerId} aria-label={`Reporting period: ${periodLabel}`} type="button" aria-haspopup="dialog" aria-expanded={periodOpen} aria-controls={periodOpen ? periodContentId : undefined} onClick={() => {
            setPeriodDraft(null);
            setPeriodOpen((o) => !o);
        }} className="art:inline-flex art:w-fit art:max-w-full art:items-center art:gap-2 art:border art:border-border art:bg-background art:px-3 art:text-sm art:font-medium art:text-foreground art:transition-colors art:hover:bg-muted/40 art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:disabled:opacity-40 art:h-10 art:rounded-full">
                <motion.span layout={reduce ? false : "position"} transition={{ layout: ARTEMIS_SPRING_LAYOUT }} className="art:shrink-0 art:text-muted-foreground" aria-hidden="true">
                  <CalendarDaysIcon size={15}/>
                </motion.span>
                <motion.span layout={reduce ? false : "position"} transition={{ layout: ARTEMIS_SPRING_LAYOUT }} className="art:min-w-0 art:truncate art:tabular-nums">{triggerText}</motion.span>
                <motion.span layout={reduce ? false : "position"} transition={{ layout: ARTEMIS_SPRING_LAYOUT }} className="art:shrink-0 art:text-muted-foreground" aria-hidden="true">
                  <ChevronDownIcon size={13} className={periodOpen ? "art:rotate-180" : undefined}/>
                </motion.span>
              </motion.button>
              {mounted
            ? artemisCreatePortal(<SessionContext.Provider value={{ open: periodOpen, value: periodValue }}>
                      <AnimatePresence>
                        {periodOpen ? (<Surface key="surface" triggerRef={periodTriggerRef} contentId={periodContentId} triggerId={periodTriggerId}>
                            <Calendar value={periodValue} onChange={setPeriodDraft} onCancel={closePeriod} onApply={(range) => {
                        setFilters((f) => ({ ...f, range: { start: range.from, end: range.to } }));
                        setExported(false);
                        closePeriod();
                    }}/>
                          </Surface>) : null}
                      </AnimatePresence>
                    </SessionContext.Provider>, document.body)
            : null}
            </div>
            <TeamMenu label="Reporting team" value={filters.team} options={TEAM_OPTIONS} onValueChange={(team: TeamId) => { setFilters((f) => ({ ...f, team })); setExported(false); }}/>
            <CompareSwitch checked={filters.compare} onCheckedChange={(compare) => { setFilters((f) => ({ ...f, compare })); setExported(false); }}/>
            <motion.button type="button" onClick={exportCsv} className={`${PILL} art:h-9 art:px-4`} {...(reduce ? {} : PRESS)}>
              <DownloadIcon className="art:size-4"/>
              Export CSV
            </motion.button>
          </fieldset>
        </header>
        <fieldset aria-label="Choose a metric" className="art:grid art:grid-cols-1 art:gap-3 art:@lg:grid-cols-2 art:@3xl:grid-cols-4">
          {view.metrics.map((m) => {
            const Icon = METRIC_ICON[m.spec.id];
            const selected = m.spec.id === metric;
            return (<motion.button {...(reduce ? {} : PRESS)} key={m.spec.id} type="button" aria-label={m.spec.label} aria-pressed={selected} onClick={() => setMetric(m.spec.id)} className={`art:items-center art:justify-center art:select-none art:disabled:pointer-events-none art:text-sm art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:h-auto art:font-normal art:text-inherit art:hover:bg-transparent art:hover:text-inherit art:flex art:min-w-0 art:flex-col art:gap-2 art:border art:bg-background art:p-4 art:text-left art:transition-colors art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:disabled:opacity-50 ${selected ? "art:border-primary" : "art:border-border art:hover:border-muted-foreground/50"} art:rounded-full`}>
                <span className="art:flex art:min-h-9 art:items-center art:justify-between art:gap-2">
                  <span className="art:text-sm art:font-normal art:leading-tight art:text-muted-foreground">{m.spec.label}</span>
                  <span aria-hidden="true" className="art:grid art:size-7 art:shrink-0 art:place-items-center art:rounded-full art:bg-muted art:text-muted-foreground art:[&>svg]:size-3.5">
                    <Icon />
                  </span>
                </span>
                <span className="art:flex art:min-h-9 art:flex-wrap art:items-center art:gap-2">
                  <Roller text={m.value} className="art:text-3xl art:font-medium art:tabular-nums art:tracking-tight"/>
                </span>
                <span className="art:flex art:min-h-4 art:flex-wrap art:items-center art:gap-x-1.5 art:gap-y-1 art:text-xs art:text-muted-foreground">
                  {m.delta ? (<>
                      <Roller prefix={m.delta.sign === "+" ? "+" : undefined} text={m.delta.sign === "-" ? `-${m.delta.number}` : m.delta.number} suffix={m.delta.suffix} duration={0.9} className={`art:font-medium art:tabular-nums ${TONE[m.delta.tone]}`}/>
                      <span>
                        {"vs. "}
                        {"previous period"}
                      </span>
                    </>) : (<span>{m.hint}</span>)}
                </span>
              </motion.button>);
        })}
        </fieldset>
        <div className="art:min-w-0 art:rounded-2xl art:border art:border-border art:bg-background">
          <div className="art:flex art:flex-wrap art:items-center art:justify-between art:gap-3 art:p-4 art:@min-[640px]/artemis:p-5">
            <div>
              <h3 className="art:text-base art:font-normal art:text-muted-foreground">{`${active.spec.label} over time`}</h3>
              <p className="art:mt-1 art:text-xs art:text-muted-foreground">Daily activity for the selected period</p>
            </div>
            <div>
              <div role="tablist" className="art:inline-flex art:items-center art:gap-1 art:rounded-full art:bg-muted art:p-0.5" aria-label="Chart style" onKeyDown={onChartTabKey}>
                {([
            ["bar", "Bar chart", "Bars", ChartColumnIcon],
            ["line", "Line chart", "Line", ChartLineIcon],
        ] as const).map(([id, aria, label, Icon]) => (<div key={id} className="art:relative">
                    {kind === id ? (<motion.span layoutId={pillId} layout="position" transition={reduce ? { duration: 0 } : INDICATOR_SPRING} className="art:absolute art:inset-0 art:bg-background art:rounded-full" style={{ borderRadius: 9999, opacity: 1 }}/>) : null}
                    <button type="button" role="tab" aria-selected={kind === id} id={`${chartIds}${id}`} aria-label={aria} aria-controls={`${chartIds}panel`} tabIndex={kind === id ? 0 : -1} onClick={() => setKind(id)} className={`art:relative art:z-10 art:inline-flex art:items-center art:justify-center art:whitespace-nowrap art:bg-transparent art:outline-none art:transition-colors art:duration-150 art:motion-reduce:delay-0 art:motion-reduce:transition-none art:h-8 art:gap-1.5 art:rounded-full art:px-3 art:py-0 art:text-xs art:font-normal art:focus-visible:ring-2 art:focus-visible:ring-ring ${kind === id ? "art:text-foreground art:delay-100" : "art:text-muted-foreground art:delay-0 art:hover:text-foreground"}`}>
                      <Icon className="art:size-3.5"/>
                      {label}
                    </button>
                  </div>))}
              </div>
            </div>
          </div>
          {view.hasPrevious ? (<div className="art:flex art:flex-wrap art:items-center art:gap-3 art:px-4 art:pb-2 art:text-xs art:@min-[640px]/artemis:px-5">
              <span className="art:inline-flex art:items-center art:gap-2 art:text-muted-foreground">
                <span aria-hidden="true" className={kind === "line" ? "art:h-0.5 art:w-4 art:rounded-full art:bg-primary" : "art:size-2 art:rounded-full art:bg-primary"}/>
                Current period
              </span>
              <motion.button {...(reduce ? {} : PRESS)} type="button" aria-pressed={previousOn} onClick={() => setPreviousOn((p) => !p)} className="art:justify-center art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:text-sm art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:p-0 art:font-normal art:hover:bg-transparent art:hover:text-inherit art:inline-flex art:h-8 art:items-center art:gap-2 art:px-2 art:text-muted-foreground art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:rounded-full">
                <span aria-hidden="true" className={kind === "line" ? "art:w-4 art:border-t art:border-dashed art:border-muted-foreground" : "art:size-2 art:rounded-full art:bg-muted-foreground/35"}/>
                Previous period
              </motion.button>
            </div>) : null}
          <div id={`${chartIds}panel`} role="tabpanel" aria-labelledby={`${chartIds}${kind}`} tabIndex={0} className="art:min-w-0 art:px-3 art:pb-5 art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-inset art:focus-visible:ring-ring art:@min-[640px]/artemis:px-4 art:@min-[640px]/artemis:pb-4">
            <figure aria-label={`${active.spec.label}: ${active.srValue} total.`} className="art:h-56 art:min-w-0 art:@min-[640px]/artemis:h-64">
              <ReportChart data={view.series[metric]} kind={kind} showPrevious={view.hasPrevious && previousOn} metricLabel={active.spec.label}/>
            </figure>
          </div>
        </div>
      </section>
      <p aria-live="polite" className="art:mt-3 art:text-xs art:text-muted-foreground">
        {exported ? "CSV exported for the selected team and period." : "Sample workspace \u00B7 April\u2013September 2026"}
      </p>
    </div>);
}

"use client";
// @zeus-internal
import { ArtemisRangeCalendar, type ArtemisDayRange } from "../../../../lib/range-calendar";
export { ArtemisCalendarSession as SessionContext, type ArtemisDayRange as DayRange } from "../../../../lib/range-calendar";
const presets = [{ "label": "Last 7 days", "value": { "from": "2026-09-24", "to": "2026-09-30" } }, { "label": "Last 30 days", "value": { "from": "2026-09-01", "to": "2026-09-30" } }, { "label": "Last 90 days", "value": { "from": "2026-07-03", "to": "2026-09-30" } }];
export function Calendar(props: {
    value: Required<ArtemisDayRange>;
    onChange?: (range: ArtemisDayRange) => void;
    onApply: (range: Required<ArtemisDayRange>) => void;
    onCancel: () => void;
}) { return <ArtemisRangeCalendar {...props} min="2026-04-01" presets={presets} clearable={true}/>; }

"use client";
// @zeus-internal
import { memo } from "react";
import { Bar, CartesianGrid, ComposedChart, Line, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts";
import type { ChartPoint } from "./model";
import { tickIndices } from "./model";
const AXIS_TICK = { fill: "var(--artemis-muted-foreground)", className: "art:text-xs" } as const;
const MARGIN = { top: 8, right: 8, bottom: 0, left: 0 } as const;
const RADIUS: [
    number,
    number,
    number,
    number
] = [3, 3, 0, 0];
const EASE = "cubic-bezier(0.16, 1, 0.3, 1)";
const DURATION = 500;
const TIP_INT = new Intl.NumberFormat("en-US", { maximumFractionDigits: 0 });
function formatTip(value: number, metricLabel: string): string {
    if (metricLabel === "On-time delivery")
        return `${value.toFixed(1)}%`;
    const integer = TIP_INT.format(Math.round(value));
    return metricLabel === "Hours logged" ? `${integer} h` : integer;
}
interface TipProps {
    active?: boolean;
    payload?: ReadonlyArray<{
        payload: ChartPoint;
    }>;
    showPrevious: boolean;
    metricLabel: string;
}
function Tip({ active, payload, showPrevious, metricLabel }: TipProps) {
    const point = payload?.[0]?.payload;
    if (!active || !point)
        return null;
    return (<div className="art:rounded-xl art:border art:border-border art:bg-background art:px-4 art:py-3 art:text-xs">
      <p className="art:mb-2 art:font-medium">{point.label}</p>
      <p className="art:flex art:justify-between art:gap-6">
        <span className="art:text-muted-foreground">{metricLabel}</span>
        <span className="art:tabular-nums">{formatTip(point.current, metricLabel)}</span>
      </p>
      {showPrevious && point.previous !== undefined ? (<p className="art:mt-2 art:flex art:justify-between art:gap-6">
          <span className="art:text-muted-foreground">{point.previousLabel ?? "Previous"}</span>
          <span className="art:tabular-nums">{formatTip(point.previous, metricLabel)}</span>
        </p>) : null}
    </div>);
}
export const ReportChart = memo(function ReportChart({ data, kind, showPrevious, metricLabel, }: {
    data: ChartPoint[];
    kind: "bar" | "line";
    showPrevious: boolean;
    metricLabel: string;
}) {
    const ticks = tickIndices(data.length).map((i) => data[i]?.label ?? "");
    const common = { data, margin: MARGIN };
    const axes = (<>
      <CartesianGrid vertical={false} stroke="var(--artemis-border)" strokeOpacity={0.5}/>
      <XAxis dataKey="label" ticks={ticks} height={30} tickLine={false} axisLine={false} tickMargin={12} interval="preserveStartEnd" minTickGap={48} tick={AXIS_TICK} padding={kind === "line" ? { left: 0, right: 0 } : undefined}/>
      <YAxis width={36} domain={[0, "auto"]} tickCount={4} tickLine={false} axisLine={false} tick={AXIS_TICK}/>
      <Tooltip cursor={kind === "line" ? { stroke: "var(--artemis-border)", strokeDasharray: "3 3" } : { fill: "var(--artemis-muted)", fillOpacity: 0.4 }} content={(p) => (<Tip active={p.active} payload={p.payload as unknown as TipProps["payload"]} showPrevious={showPrevious} metricLabel={metricLabel}/>)}/>
    </>);
    return (<ResponsiveContainer width="100%" height="100%" minWidth={0}>
      {kind === "bar" ? (<ComposedChart {...common} barGap={1} barCategoryGap="20%" maxBarSize={20}>
          {axes}
          {showPrevious ? (<Bar dataKey="previous" fill="var(--artemis-muted-foreground)" fillOpacity={0.35} radius={RADIUS} isAnimationActive={false}/>) : null}
          <Bar dataKey="current" fill="var(--artemis-primary)" radius={RADIUS} animationDuration={DURATION} animationEasing={EASE}/>
        </ComposedChart>) : (<ComposedChart {...common}>
          {axes}
          {showPrevious ? (<Line dataKey="previous" type="linear" stroke="var(--artemis-muted-foreground)" strokeOpacity={0.5} strokeWidth={1.5} strokeDasharray="3 4" dot={false} isAnimationActive={false}/>) : null}
          <Line dataKey="current" type="linear" stroke="var(--artemis-primary)" strokeWidth={2} dot={false} activeDot={{ stroke: "var(--artemis-background)" }} animationDuration={DURATION} animationEasing={EASE}/>
        </ComposedChart>)}
    </ResponsiveContainer>);
});

// @zeus-internal
const GUARD_ATTRIBUTE = "data-radix-focus-guard";
const MARKER_ATTRIBUTE = "data-aria-hidden";
const LOCK_ATTRIBUTE = "data-scroll-locked";
let guardCount = 0;
function createFocusGuard(): HTMLSpanElement {
    const guard = document.createElement("span");
    guard.setAttribute(GUARD_ATTRIBUTE, "");
    guard.tabIndex = 0;
    guard.style.outline = "none";
    guard.style.opacity = "0";
    guard.style.position = "fixed";
    guard.style.pointerEvents = "none";
    return guard;
}
export function acquireFocusGuards(): () => void {
    const existing = document.querySelectorAll(`[${GUARD_ATTRIBUTE}]`);
    document.body.insertAdjacentElement("afterbegin", existing[0] ?? createFocusGuard());
    document.body.insertAdjacentElement("beforeend", existing[1] ?? createFocusGuard());
    guardCount += 1;
    return () => {
        if (guardCount === 1) {
            for (const node of Array.from(document.querySelectorAll(`[${GUARD_ATTRIBUTE}]`)))
                node.remove();
        }
        guardCount -= 1;
    };
}
const hiddenCount = new WeakMap<Element, number>();
const markerCount = new WeakMap<Element, number>();
const alreadyHiddenNodes = new WeakSet<Element>();
export function hideOthers(target: Element): () => void {
    const body = target.ownerDocument.body;
    const targets: Element[] = [target, ...Array.from(body.querySelectorAll("[aria-live], script"))];
    const stop = new Set<Element>(targets);
    const keep = new Set<Node>();
    const keepWithAncestors = (node: Node | null) => {
        if (!node || keep.has(node))
            return;
        keep.add(node);
        keepWithAncestors(node.parentNode);
    };
    for (const node of targets)
        keepWithAncestors(node);
    const hidden: Element[] = [];
    const walk = (parent: Element) => {
        if (stop.has(parent))
            return;
        for (const node of Array.from(parent.children)) {
            if (keep.has(node)) {
                walk(node);
                continue;
            }
            const attribute = node.getAttribute("aria-hidden");
            const wasHidden = attribute !== null && attribute !== "false";
            const count = (hiddenCount.get(node) ?? 0) + 1;
            const markers = (markerCount.get(node) ?? 0) + 1;
            hiddenCount.set(node, count);
            markerCount.set(node, markers);
            hidden.push(node);
            if (count === 1 && wasHidden)
                alreadyHiddenNodes.add(node);
            if (markers === 1)
                node.setAttribute(MARKER_ATTRIBUTE, "true");
            if (!wasHidden)
                node.setAttribute("aria-hidden", "true");
        }
    };
    walk(body);
    return () => {
        for (const node of hidden) {
            const count = (hiddenCount.get(node) ?? 1) - 1;
            const markers = (markerCount.get(node) ?? 1) - 1;
