}
export interface MetricSpec {
    id: MetricId;
    label: string;
    aggregation: "sum" | "average";
}
export const METRICS: ReadonlyArray<MetricSpec> = [
    { id: "completed", label: "Completed tasks", aggregation: "sum" },
    { id: "hours", label: "Hours logged", aggregation: "sum" },
    { id: "onTime", label: "On-time delivery", aggregation: "average" },
    { id: "active", label: "Active teammates", aggregation: "average" },
];
export interface ChartPoint {
    key: string;
    label: string;
