}
const INT = new Intl.NumberFormat("en-US", { maximumFractionDigits: 0 });
function formatValue(id: MetricId, value: number): string {
    if (id === "onTime")
        return `${value.toFixed(1)}%`;
    if (id === "hours")
        return `${INT.format(Math.round(value))}\u00A0h`;
    return INT.format(Math.round(value));
}
function aggregate(id: MetricId, rows: DailyRow[]): number {
    const values = rows.map((r) => r[id]);
    const sum = values.reduce((a, b) => a + b, 0);
    return METRICS.find((m) => m.id === id)?.aggregation === "sum" ? sum : rows.length ? sum / rows.length : 0;
