export function buildReport(filters: ReportingFilters): ReportView {
    const startN = dayNumber(parseIso(filters.range.start));
    const endN = dayNumber(parseIso(filters.range.end));
    const days = endN - startN + 1;
    const prevStart = startN - days;
    const hasPrevious = filters.compare && prevStart >= MIN_N;
    const current: DailyRow[] = [];
    const previous: DailyRow[] = [];
    for (let i = 0; i < days; i++) {
        const row = dailyRow(filters.team, startN + i);
        if (row)
            current.push(row);
        if (hasPrevious) {
            const prev = dailyRow(filters.team, prevStart + i);
            if (prev)
                previous.push(prev);
        }
    }
    const metrics = METRICS.map((spec): MetricView => {
        const cur = aggregate(spec.id, current);
        const value = formatValue(spec.id, cur);
        let delta: MetricView["delta"] = null;
        if (hasPrevious) {
            const prev = aggregate(spec.id, previous);
            const raw = spec.id === "onTime" ? cur - prev : prev ? ((cur - prev) / prev) * 100 : 0;
            const number = Math.abs(raw).toFixed(1);
            const zero = raw === 0;
            delta = {
                sign: zero ? "" : raw > 0 ? "+" : "-",
                number,
                suffix: spec.id === "onTime" ? "\u00A0pp" : "%",
                tone: zero ? "neutral" : raw > 0 ? "positive" : "negative",
            };
        }
        return {
            spec,
            value,
            srValue: value,
            delta,
            hint: spec.aggregation === "sum" ? "Period total" : "Daily average",
        };
    });
    const series = {} as Record<MetricId, ChartPoint[]>;
    for (const spec of METRICS) {
        series[spec.id] = current.map((row, i) => {
            const day = fromDayNumber(startN + i);
            const point: ChartPoint = { key: toIso(day), label: shortDate(day), current: row[spec.id] };
            if (hasPrevious) {
                const p = previous[i];
                if (p) {
                    point.previous = p[spec.id];
