        return [0];
    const step = Math.ceil((n - 1) / 5);
    const out: number[] = [];
    for (let i = 0; i < n - 1; i += step)
        out.push(i);
    out.push(n - 1);
    return out;
}
export function reportCsv(filters: ReportingFilters): {
    filename: string;
    body: string;
} {
    const startN = dayNumber(parseIso(filters.range.start));
    const endN = dayNumber(parseIso(filters.range.end));
    const lines = [["Date", "Team", "Completed tasks", "Hours logged", "On-time delivery", "Active teammates"]];
    for (let n = startN; n <= endN; n++) {
        const row = dailyRow(filters.team, n);
        if (!row)
            continue;
        lines.push([
            toIso(fromDayNumber(n)),
            filters.team,
            String(row.completed),
            String(row.hours),
            String(row.onTime),
            String(row.active),
        ]);
    }
    return {
        filename: `team-report-${filters.range.start}-${filters.range.end}.csv`,
        body: lines.map((cells) => cells.map((c) => `"${c.replace(/"/g, "\"\"")}"`).join(",")).join("\r\n"),
    };
}

